const hubs = ["Lagos", "Ibadan", "Kano", "Kaduna", "Calabar"];
const roads = [["Lagos", "Ibadan"], ["Kano", "Kaduna"]];

function countGroups(hubs, roads) {
  const graph = new Map(hubs.map((h) => [h, []]));
  for (const [a, b] of roads) {
    graph.get(a).push(b);
    graph.get(b).push(a);
  }
  const seen = new Set();
  let groups = 0;
  for (const start of hubs) {
    if (seen.has(start)) continue;
    groups++;
    seen.add(start);
    const stack = [start];
    while (stack.length > 0) {
      for (const next of graph.get(stack.pop())) {
        if (!seen.has(next)) {
          seen.add(next);
          stack.push(next);
        }
      }
    }
  }
  return groups;
}

