const hall = [
  "..x..",
  "x.xx.",
  "..x..",
  "xx.x.",
];

function largestBlock(rows) {
  const seen = new Set();
  let best = 0;
  for (let r = 0; r < rows.length; r++) {
    for (let c = 0; c < rows[r].length; c++) {
      if (rows[r][c] !== "." || seen.has(`${r},${c}`)) continue;
      seen.add(`${r},${c}`);
      const stack = [[r, c]];
      let size = 0;
      while (stack.length > 0) {
        const [cr, cc] = stack.pop();
        size++;
        for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const nr = cr + dr;
          const nc = cc + dc;
          if (nr < 0 || nr >= rows.length || nc < 0 || nc >= rows[nr].length) continue;
          if (rows[nr][nc] !== "." || seen.has(`${nr},${nc}`)) continue;
          seen.add(`${nr},${nc}`);
          stack.push([nr, nc]);
        }
      }
      best = Math.max(best, size);
    }
  }
  return best;
}

console.log(largestBlock(hall));

