const roads = {
  Lagos: { Ibadan: 7500, Benin: 19000 },
  Ibadan: { Lagos: 7500, Ilorin: 9500 },
  Ilorin: { Ibadan: 9500, Abuja: 28000 },
  Benin: { Lagos: 19000, Abuja: 30000 },
  Abuja: { Ilorin: 28000, Benin: 30000 },
};

function cheapest(roads, start) {
  const cost = { [start]: 0 };
  const done = new Set();
  while (true) {
    let city = null;
    for (const c in cost) {
      if (!done.has(c) && (city === null || cost[c] < cost[city])) city = c;
    }
    if (city === null) return cost;
    done.add(city);
    for (const [next, naira] of Object.entries(roads[city])) {
      if (cost[next] === undefined || cost[city] + naira < cost[next]) cost[next] = cost[city] + naira;
    }
  }
}

const cost = cheapest(roads, "Lagos");
console.log(["Ibadan", "Ilorin", "Abuja", "Benin"].map((c) => `${c} ${cost[c]}`).join(" "));

