function circular(transfers) {
  const graph = new Map();
  for (const [from, to] of transfers) {
    if (!graph.has(from)) graph.set(from, []);
    if (!graph.has(to)) graph.set(to, []);
    graph.get(from).push(to);
  }
  const state = new Map();
  function visit(account) {
    state.set(account, "on path");
    for (const next of graph.get(account)) {
      if (state.get(next) === "on path") return true;
      if (!state.has(next) && visit(next)) return true;
    }
    state.set(account, "finished");
    return false;
  }
  for (const account of graph.keys()) {
    if (!state.has(account) && visit(account)) return true;
  }
  return false;
}

console.log(
  circular([["Ada", "Bola"], ["Ada", "Chidi"], ["Bola", "Chidi"]]),
  circular([["Ada", "Bola"], ["Bola", "Chidi"], ["Chidi", "Dayo"], ["Dayo", "Bola"]]),
);

