const roads = { A: [["B", 10], ["C", 1]], B: [["D", 1]], C: [["B", 2]], D: [] };
const dist = new Map([["A", 0]]);
const done = new Set();
const queue = [["A", 0]];
let pops = 0;
while (queue.length > 0) {
  queue.sort((x, y) => y[1] - x[1]);
  const [city, km] = queue.pop();
  pops++;
  if (done.has(city)) continue;
  done.add(city);
  for (const [next, length] of roads[city]) {
    if (!dist.has(next) || km + length < dist.get(next)) {
      dist.set(next, km + length);
      queue.push([next, km + length]);
    }
  }
}
